function helpButton(key){return '<button type="button" class="info-button" data-help="'+esc(key)+'" aria-haspopup="dialog" aria-controls="help-dialog" aria-label="'+esc(HELP[key]&&HELP[key][0]||'Magyarázat')+'">i</button>';}
