function stats(){try{return typeof CLUBSTATS!=='undefined'?CLUBSTATS:window.CLUBSTATS;}catch(_){return window.CLUBSTATS;}}
function plainObject(v){return !!v&&typeof v==='object'&&!Array.isArray(v)&&(Object.getPrototypeOf(v)===Object.prototype||Object.getPrototypeOf(v)===null);}
function allowedKeys(v,keys,label){if(!plainObject(v)||Object.keys(v).some(k=>!keys.includes(k)))throw new Error(label+': ismeretlen vagy tiltott mező.');}
function validatedScenario(value,teamId){allowedKeys(value,['paths','doubles'],'Összeállítás');if(arr(value.paths).length!==4||value.paths.some(p=>!Array.isArray(p)||p.length!==4)||arr(value.doubles).length!==2||value.doubles.some(p=>!Array.isArray(p)||p.length!==2))throw new Error('Az összeállításban négy egyéni hely és két kéttagú páros szükséges.');const roster=new Set(arr(tm.get(teamId)&&tm.get(teamId).roster)),paths=value.paths.map(p=>p.slice()),doubles=value.doubles.map(p=>p.slice());for(const id of [...paths.flat(),...doubles.flat()])if(id!==null&&(typeof id!=='string'||!uuid.test(id)||!roster.has(id)))throw new Error('Az összeállítás csak a csapat jelenlegi nyilvános keretének érvényes azonosítóit tartalmazhatja.');const initial=paths.map(p=>p[0]).filter(Boolean);if(new Set(initial).size!==initial.length)throw new Error('Egy kezdőjátékos csak egy helyen szerepelhet.');let changes=0;for(const p of paths)for(let i=1;i<4;i++)if(p[i]!==p[i-1]){changes++;if(p[i]!==null&&initial.includes(p[i]))throw new Error('Kezdőjátékos nem léphet át másik egyéni helyre.');}if(changes>1)throw new Error('Csapatonként legfeljebb egy egyéni csere menthető.');for(let i=0;i<4;i++){const ids=paths.map(p=>p[i]).filter(Boolean);if(new Set(ids).size!==ids.length)throw new Error('Ugyanabban az egyéni körben nem ismétlődhet játékos.');}const ds=doubles.flat().filter(Boolean);if(new Set(ds).size!==ds.length)throw new Error('Egy játékos legfeljebb egy párosban szerepelhet.');return {paths,doubles};}
function validateOverrides(value){if(!plainObject(value)||Object.keys(value).length>FIXTURES.length)throw new Error('Érvénytelen mentett mérkőzéslista.');const clean={};for(const [id,pair] of Object.entries(value)){const f=FIXTURES.find(x=>x.id===id);if(!uuid.test(id)||!f||f.known)throw new Error('Csak ismert azonosítójú, még nem lejátszott találkozóhoz menthető felállás.');allowedKeys(pair,['home','away'],'Mérkőzésfelállás');clean[id]={home:validatedScenario(pair.home,f.home),away:validatedScenario(pair.away,f.away)};}return clean;}
function configEnvelope(){const errors=draftErrors();if(errors.length)throw new Error(errors.join(' '));const c=draftConfig();c.overrides=validateOverrides(c.overrides);return {schema:CONFIG_SCHEMA,version:3,dataRevision,cutoffUtc:dataCutoff,config:c};}
function validateConfigFile(value){allowedKeys(value,['schema','version','dataRevision','cutoffUtc','config'],'Beállításfájl');if(value.schema!==CONFIG_SCHEMA||value.version!==3)throw new Error('Nem támogatott beállításfájl-verzió.');if(value.dataRevision!==dataRevision||value.cutoffUtc!==dataCutoff)throw new Error('A fájl más adatverzióhoz vagy adatzáráshoz készült. Nem alkalmazzuk automatikusan.');const c=value.config;allowedKeys(c,['modelId','n','seed','horizon','formMultiplier','overrides'],'Számítási beállítás');if(typeof c.modelId!=='string'||!Object.prototype.hasOwnProperty.call(MODELS,c.modelId))throw new Error('Ismeretlen modellazonosító.');if(!Number.isSafeInteger(c.n)||c.n<1||c.n>100000)throw new Error('A futásszám 1–100 000 közötti egész legyen.');if(!Number.isSafeInteger(c.seed)||c.seed<0||c.seed>4294967295)throw new Error('Érvénytelen véletlenmag.');if(![9,18].includes(c.horizon)||!finite(c.formMultiplier)||c.formMultiplier<0||c.formMultiplier>5)throw new Error('Érvénytelen időtáv vagy formaingadozás.');return {modelId:c.modelId,n:c.n,seed:c.seed,horizon:c.horizon,formMultiplier:c.formMultiplier,overrides:validateOverrides(c.overrides)};}
function applyConfig(c){state.modelId=c.modelId;state.n=c.n;state.seed=String(c.seed);state.horizon=c.horizon;state.formMultiplier=c.formMultiplier;state.overrides=c.overrides;state.lineups={};for(const [id,pair] of Object.entries(c.overrides))state.lineups[id]={home:{mode:'imported',scenario:clone(pair.home),manual:null},away:{mode:'imported',scenario:clone(pair.away),manual:null}};state.error='';}
function persistConfig(){if(!state.storageEnabled)return;const errors=draftErrors();if(errors.length){state.storageMessage='Az érvénytelen mezőket nem mentettük. Javítás után a következő módosítás újra ment.';return;}try{localStorage.setItem(STORAGE_KEY,JSON.stringify({version:3,enabled:true,envelope:configEnvelope()}));state.storageMessage='A beállításokat ez a böngésző megjegyzi. Az eredmény nincs eltárolva.';}catch(e){state.storageEnabled=false;state.storageMessage='A böngésző nem engedélyezi a helyi mentést. A JSON export ettől még használható.';}}
function restoreConfig(){try{const text=localStorage.getItem(STORAGE_KEY);if(!text)return;const saved=JSON.parse(text);allowedKeys(saved,['version','enabled','envelope'],'Helyi mentés');if(saved.version!==3||saved.enabled!==true)return;const c=validateConfigFile(saved.envelope);applyConfig(c);state.storageEnabled=true;state.storageMessage='A korábban engedélyezett helyi beállításokat visszatöltöttük. A mutatott eredmény továbbra is a külön jelölt futás.';}catch(e){state.storageEnabled=false;if(e&&e.name==='SecurityError'){state.storageAvailable=false;state.storageMessage='';}else{state.storageMessage='A korábbi helyi beállítás ehhez az adatverzióhoz nem tölthető be. A saját beállítások törlésével tiszta alaphelyzetből indulhatsz.';}}}
function exportConfig(){try{const errors=draftErrors();if(errors.length)throw new Error(errors.join(' '));download(JSON.stringify(configEnvelope(),null,2),'application/json;charset=utf-8','topspin-beallitasok-v3.json');}catch(e){reportError('A beállításfájl nem menthető',e);}}
async function importConfig(file){if(state.running||!file)return;try{if(file.size>1024*1024)throw new Error('A beállításfájl legfeljebb 1 MB lehet.');const c=validateConfigFile(JSON.parse(await file.text()));if(state.running)throw new Error('Futó számítás közben nem cserélhetők a beállítások.');applyConfig(c);persistConfig();preserveFocus(renderAll);refreshPreview();toast('Beállítások betöltve. Az új eredményhez külön indíts szimulációt.');}catch(e){reportError('A fájlt nem alkalmaztuk',e);}finally{$('config-file').value='';}}
function resetLocal(){if(state.running)return;try{localStorage.removeItem(STORAGE_KEY);}catch(_){}fixtureRuns.clear();state.storageEnabled=false;state.storageMessage='A saját helyi mentés és minden mentett felállás törölve. Más látogató adatai nem változtak.';state.modelId=initialModel;state.n=Number(initialData&&initialData.n)||20000;state.seed=String(initialData&&initialData.seed!=null?initialData.seed:APP.meta?.seed??20261017);state.horizon=9;state.formMultiplier=1;state.overrides={};state.lineups={};state.fixtureId=initialFixture&&initialFixture.id;state.playerId=null;state.error='';if(initialData)state.result={data:initialData,config:{modelId:initialModel,n:Number(initialData.n),seed:Number(initialData.seed),horizon:initialData.horizons?.['18']?18:9,formMultiplier:1,overrides:{}},source:'precomputed',at:null};preserveFocus(renderAll);refreshPreview();toast('Saját beállítások alaphelyzetben.');}
function saveOverride(){if(state.running)return;const f=currentFixture();if(!f||f.known)return;try{const errors=[...sideErrors('home'),...sideErrors('away')];if(errors.length)throw new Error(errors.join(' '));const candidate={...state.overrides,[f.id]:{home:cleanScenario(getScenario('home')),away:cleanScenario(getScenario('away'))}};state.overrides=validateOverrides(candidate);persistConfig();preserveFocus(()=>{renderControls();renderFixture();});toast('Felállás elmentve ehhez a meccshez. A korábbi mentések is megmaradtak.');}catch(e){reportError('A felállás nem menthető',e);}}
function removeOverride(id){if(state.running)return;delete state.overrides[id];persistConfig();preserveFocus(()=>{renderControls();renderFixture();});toast('A mentés törölve; ez a meccs ismét kevert felállással fut majd.');}
function overrideReview(){const ids=Object.keys(state.overrides);if(!ids.length)return '<p class="chart-note">Még nincs mentett saját felállás. Az előnézet önmagában nem módosítja a szezonfutást.</p>';return '<section class="override-review" aria-label="Mentett összeállítások"><div class="button-row"><strong>'+ids.length+' mérkőzés mentett felállással</strong>'+helpButton('overrides')+'<button class="btn subtle small danger" data-action="remove-all-overrides"'+(state.running?' disabled':'')+'>Összes mentés törlése</button></div>'+ids.sort((a,b)=>FIXTURES.find(f=>f.id===a).round-FIXTURES.find(f=>f.id===b).round).map(id=>{const f=FIXTURES.find(x=>x.id===id);return '<div class="override-item"><div><strong>'+f.round+'. forduló</strong> · '+esc(teamShort(f.home)+' – '+teamShort(f.away))+(Number(f.round)>state.horizon?' <span class="tag amber">Csak a teljes szezonban</span>':'')+'</div><div class="button-row"><button class="btn subtle small" data-open-saved="'+esc(id)+'"'+(state.running?' disabled':'')+'>Átnézem</button><button class="btn subtle small danger" data-remove-override="'+esc(id)+'"'+(state.running?' disabled':'')+'>Törlés</button></div></div>';}).join('')+'</section>';}

