function compactName(id){if(id==null)return 'Hiányzik';const parts=playerName(id).trim().split(/\s+/);if(parts.length<2)return parts[0];return parts[0]+' '+parts.slice(1).map(s=>s.charAt(0)+'.').join(' ');}
